insert into public.components (id, name, category, description, unit_price, weight_grams, specs, compatibility) values
  ('arduino-uno', 'Arduino Uno', 'Microcontrollers', 'ATmega328P board with 14 digital and 6 analog pins.', 650, 25, '5V logic, 7–12V input, 20 mA per I/O pin', '5V logic. Sensors must accept 5V signals or use a level shifter.'),
  ('esp32', 'ESP32 Dev Board', 'Microcontrollers', 'Wi-Fi and Bluetooth microcontroller board.', 450, 10, '3.3V logic (GPIO not 5V tolerant)', '3.3V logic. Connecting 5V sensors directly can damage GPIO pins.'),
  ('ultrasonic', 'Ultrasonic Sensor HC-SR04', 'Sensors', 'Distance measurement via ultrasonic echo.', 90, 8, '5V supply, 2–400 cm range', 'Echo output is 5V. Use a voltage divider with 3.3V boards.'),
  ('soil-moisture', 'Soil Moisture Sensor', 'Sensors', 'Analog soil-moisture probe for watering systems.', 120, 10, '3.3–5V, analog output', 'Analog output. Corrosion shortens probe life.'),
  ('dht11', 'DHT11 Temperature & Humidity Sensor', 'Sensors', 'Digital temperature and humidity sensor.', 110, 4, '3–5.5V, 0–50 °C, ±2 °C', 'Single-wire data line. Needs a pull-up resistor (about 10 kΩ).'),
  ('pir', 'PIR Motion Sensor HC-SR501', 'Sensors', 'Passive infrared motion detector.', 80, 5, '5–20V supply, digital output', 'Needs about 30–60 s warm-up after power-on.'),
  ('ldr', 'LDR Light Sensor', 'Sensors', 'Light-dependent resistor for dark/light sensing.', 20, 3, 'Resistance falls as light increases', 'Use in a voltage divider or with a transistor switch.'),
  ('ir-obstacle', 'IR Obstacle Sensor', 'Sensors', 'Infrared proximity sensor with digital output.', 60, 3, '3–5V, digital output, adjustable range', 'Adjust the potentiometer for detection range.'),
  ('servo', 'Servo Motor SG90', 'Motors & Actuators', 'Micro servo with 0–180° travel.', 140, 9, '4.8–6V, 1.8 kg·cm, 0–180°', 'Draws peak current. Power from an external 5V supply, not the Arduino 5V pin.'),
  ('dc-motor', 'DC Geared Motor', 'Motors & Actuators', 'Low-voltage geared DC motor for wheels or lifts.', 120, 30, '3–6V, approx. 100–200 RPM', 'Needs a motor driver. Never drive directly from a GPIO pin.'),
  ('motor-driver', 'L298N Motor Driver', 'Motors & Actuators', 'Dual H-bridge motor driver module.', 220, 30, '5–35V motor supply, 2 A per channel', 'Voltage drop of about 2V across the driver. Heat sink advised.'),
  ('relay', '5V Relay Module', 'Motors & Actuators', 'Single-channel relay for switching external loads.', 70, 15, '5V coil, check contact rating on label', 'Confirm trigger level (active-low or active-high) and contact rating before switching loads.'),
  ('water-pump', 'Mini Submersible Water Pump', 'Fluidics', 'Small 5V DC submersible pump.', 250, 40, '3–5V DC, approx. 100–150 mA (typical)', 'Verify voltage and current draw against the supply and relay.'),
  ('tubing', 'Silicone Tubing (1 m set)', 'Fluidics', 'Flexible tubing for water delivery.', 60, 20, '4 mm inner diameter (typical)', 'Match tubing diameter to the pump outlet.'),
  ('lcd16x2', '16x2 LCD Display (I2C)', 'Displays & Output', 'Character LCD with I2C backpack.', 180, 40, '5V, 16 characters × 2 lines', 'Confirm the I2C address (commonly 0x27 or 0x3F).'),
  ('led', 'LED 5 mm', 'Displays & Output', 'Standard 5 mm indicator LED.', 2, 0.2, 'About 2V forward voltage, 20 mA', 'Always use a series resistor.'),
  ('buzzer', 'Active Buzzer', 'Displays & Output', 'Self-oscillating buzzer for alerts.', 25, 3, '3–5V DC', 'Active buzzers have a fixed tone. Passive buzzers need PWM.'),
  ('resistor', 'Resistor 220 Ω', 'Passives', 'Carbon film resistor, 220 ohm, 1/4 W.', 1, 0.1, '220 Ω, 1/4 W', ''),
  ('jumper', 'Jumper Wires (per wire)', 'Wiring & Prototyping', 'Dupont jumper wires for breadboard prototyping.', 1, 0.5, 'Male–male / male–female', ''),
  ('breadboard', 'Breadboard (830 points)', 'Wiring & Prototyping', 'Solderless prototyping board.', 150, 40, '830 tie points', ''),
  ('battery-holder', 'Battery Holder (4 × AA)', 'Power', 'Holder for four AA cells.', 40, 15, '6V nominal', 'Check the current rating against the load.'),
  ('power-supply', '5V 2A Power Adapter', 'Power', 'Regulated 5V DC adapter.', 200, 60, '5V, 2 A', 'Confirm total load (pump, relay, controller) stays below 2 A.')
insert into public.products (id, name, aliases, category, description, difficulty, duration_minutes, new_product_price, consumables_cost, icon, requires_spec_check, instructions, safety_notes, compatibility_notes) values
  ('plant-watering', 'Automatic Plant Watering System', array['Plant Watering System','Smart Watering System']::text[], 'Home & Garden', 'Waters a plant automatically when the soil moisture drops below a threshold.', 'Intermediate', 180, 1999, 50, 'sprout', true, '["Read the pump’s rated voltage and current, and the power supply’s output, before wiring anything.","Mount the soil moisture sensor in the pot. Connect VCC and GND to the 5V and GND rails, and its analog output to an analog pin.","Connect the relay module’s signal pin to a digital pin, and power its coil from the 5V rail.","Wire the pump through the relay’s switched contacts, powered from the external supply. Never power the pump from the Arduino 5V pin.","Attach tubing to the pump outlet. Test the pump in a container of water before placing it near the plant.","Upload a sketch that reads the sensor and switches the relay when the reading falls below a threshold you calibrate.","Calibrate in dry and wet soil, run a short pump test, and check for leaks."]'::jsonb, '["Keep water away from powered electronics. Use a drip tray and a waterproof enclosure for the controller.","Disconnect power before changing any wiring.","Do not exceed the relay’s contact rating or the power supply’s current rating.","Do not connect mains wiring yourself. Use a commercially rated adapter and seek a qualified electrician for any mains work."]'::jsonb, '["Relay trigger level (active-low or active-high) must match the sketch.","Pump current draw must sit below the power supply rating with headroom.","An ESP32 is 3.3V logic. Check sensor voltage levels before substituting it for the Arduino Uno."]'::jsonb),
  ('weather-station', 'Mini Weather Station', array['Weather Station','Digital Weather Station']::text[], 'Environment', 'Displays temperature and humidity readings on a small LCD.', 'Beginner', 150, 2499, 80, 'cloud', false, '["Wire the DHT11: VCC to 5V, GND to GND, data to a digital pin, with a pull-up resistor (about 10 kΩ) between data and VCC.","Connect the I2C LCD to the Uno’s SDA and SCL pins, with 5V and GND.","Install the DHT and I2C LCD libraries in the Arduino IDE.","Upload a sketch that reads temperature and humidity every few seconds and prints them on the LCD.","Compare readings with a reference thermometer.","Place the sensor away from heat sources and direct sunlight."]'::jsonb, '["Power the system from USB or a 5V adapter only. Do not wire into mains.","Keep the sensor away from heating elements.","The DHT11 is a low-cost sensor (±2 °C). Do not treat its readings as calibrated instrumentation."]'::jsonb, '["DHT11 needs a pull-up resistor on the data line.","Confirm the LCD’s I2C address before uploading the sketch."]'::jsonb),
  ('smart-dustbin', 'Smart Dustbin', array['Smart Trash Bin','Automatic Dustbin']::text[], 'Smart Home', 'Opens the lid automatically when a person approaches, using distance sensing and a servo.', 'Intermediate', 240, 1899, 60, 'trash', true, '["Mount the HC-SR04 at the lid opening, facing into the approach area.","Connect trigger and echo to two digital pins, with VCC to 5V and GND to GND.","Power the SG90 from the external 5V supply, with a common ground to the Arduino GND. Connect its signal to a PWM pin.","Upload a sketch that measures distance and rotates the lid open when an object is within about 20 cm.","Test the lid mechanism without the bin first, and set the open angle and hold time.","Attach the lid and secure the servo.","Run a 30-minute test and check that the servo does not stall."]'::jsonb, '["Keep fingers clear of the servo arm and lid hinge.","Do not run the servo from the Arduino 5V pin under load.","Seal electronics from the waste area to prevent moisture and contamination."]'::jsonb, '["Verify the servo’s voltage and stall torque against the supply.","The HC-SR04 echo pin outputs 5V. Use a divider with 3.3V boards."]'::jsonb),
  ('obstacle-robot', 'Obstacle-Avoiding Robot', array['Obstacle Avoiding Robot','Robot Car']::text[], 'Robotics', 'A two-wheel robot that drives forward and turns away from obstacles.', 'Advanced', 300, 2499, 120, 'bot', true, '["Mount the two DC motors on the chassis and check that the gearing and wheel size suit your build.","Connect the L298N outputs to the motors. Power the driver’s motor supply from the battery holder, and check the motor rating against the battery voltage.","Connect the enable pins to PWM pins and the direction pins to digital pins.","Mount the HC-SR04 at the front of the chassis, facing forward.","Upload code that drives forward, and when an obstacle is within about 20 cm, stops, reverses briefly, and turns.","Test with the wheels off the ground first.","Test on the floor at low speed."]'::jsonb, '["Keep the robot off the ground while testing motors.","The L298N gets hot. Ensure ventilation and use a heat sink.","Never short battery terminals. Remove batteries when the robot is stored.","Verify all motor and driver ratings against their datasheets before powering up."]'::jsonb, '["L298N voltage drop reduces the voltage available to the motors.","Confirm motor voltage and current ratings before choosing the battery."]'::jsonb),
  ('led-emergency', 'LED Emergency Light', array['Emergency Light','LED Night Light']::text[], 'Lighting', 'A battery-powered LED light that switches on in darkness.', 'Beginner', 60, 599, 20, 'bulb', false, '["Wire each LED in series with a 220 Ω resistor. Check the LED polarity before connecting.","Connect the LED branches in parallel across the battery holder.","Plan the LDR circuit using a voltage divider and a transistor switch. Test it with a multimeter before connecting the LEDs.","Insert the batteries and check the brightness and total current draw.","Test the light in a dark room, then in daylight."]'::jsonb, '["Observe LED polarity. Reversed LEDs will not light.","Do not exceed the battery holder’s rated current.","Do not connect any mains supply to this build."]'::jsonb, '["The LDR transistor circuit needs verification with a multimeter before use."]'::jsonb),
  ('temp-monitor', 'Temperature Monitoring System', array['Digital Temperature Monitor','Temperature Monitor']::text[], 'Environment', 'Reads temperature and raises an audible and visual alert above a set limit.', 'Beginner', 120, 1299, 40, 'thermo', false, '["Wire the DHT11 with a pull-up resistor on the data line.","Connect the I2C LCD to the SDA and SCL pins.","Connect the buzzer to a digital pin through a suitable driver if your buzzer requires it.","Upload a sketch that prints the temperature and sounds the buzzer above your chosen limit.","Test by warming the sensor gently and checking the alarm threshold."]'::jsonb, '["Do not place the sensor near heating elements or flames.","Power from USB or a 5V adapter only."]'::jsonb, '["DHT11 requires a pull-up resistor on the data line."]'::jsonb),
  ('motion-alarm', 'Motion Alarm', array['Motion Detector','PIR Alarm']::text[], 'Security', 'Sounds a buzzer and lights an LED when motion is detected.', 'Beginner', 90, 899, 30, 'radar', false, '["Connect the PIR output to a digital pin and power it from the 5V rail.","Connect the buzzer and each LED to digital pins. Use a series resistor for each LED.","Upload a sketch that triggers the alarm on motion and holds it for a set time.","Allow about 60 seconds for the PIR to warm up, then test by walking in front of it."]'::jsonb, '["Keep the power supply at a safe distance from the breadboard and do not short the rails.","Do not connect the alarm to mains wiring."]'::jsonb, '["PIR sensors need a warm-up period after power-on."]'::jsonb)
